<?php
require dirname(__DIR__).'/app/bootstrap.php';
use Divigamana\Support\{Database,Session,Csrf};
$u=Session::user(); if(!$u||$u['role']!=='admin'){http_response_code(403);exit('Administrator access required. Create an admin user directly in MySQL, then sign in through the demo flow.');}
$p=Database::pdo();$metrics=['Users'=>$p->query('SELECT COUNT(*) FROM users')->fetchColumn(),'Active subscriptions'=>$p->query("SELECT COUNT(*) FROM user_subscriptions WHERE status='active' AND ends_at>NOW()")->fetchColumn(),'Requests'=>$p->query('SELECT COUNT(*) FROM horoscope_requests')->fetchColumn(),'Simulated charges'=>$p->query("SELECT COUNT(*) FROM payment_transactions WHERE is_simulated=1")->fetchColumn(),'AI tokens'=>$p->query('SELECT COALESCE(SUM(total_tokens),0) FROM ai_usage_logs')->fetchColumn(),'Failed AI'=>$p->query("SELECT COUNT(*) FROM horoscope_requests WHERE status='failed'")->fetchColumn()];$popular=$p->query('SELECT s.slug,COUNT(q.id) n FROM service_catalog s LEFT JOIN horoscope_requests q ON q.service_id=s.id GROUP BY s.id ORDER BY n DESC')->fetchAll();
?><!doctype html><meta charset="utf-8"><title>Divigamana Admin</title><style>body{font:16px system-ui;background:#0b1026;color:#f9f5ed;margin:40px;max-width:1000px}h1{color:#d5ad63}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card,table{background:#171333;border:1px solid #ffffff22;padding:18px;border-radius:10px}b{font-size:1.6rem;color:#d5ad63}table{width:100%;margin-top:25px;border-collapse:collapse}td,th{padding:10px;text-align:left;border-bottom:1px solid #ffffff18}</style><h1>Divigamana admin foundation</h1><p>CSRF token available for future state-changing controls: <?=htmlspecialchars(Csrf::token())?></p><div class="grid"><?php foreach($metrics as $k=>$v):?><div class="card"><small><?=$k?></small><br><b><?=$v?></b></div><?php endforeach?></div><table><tr><th>Service popularity</th><th>Requests</th></tr><?php foreach($popular as $x):?><tr><td><?=htmlspecialchars($x['slug'])?></td><td><?=$x['n']?></td></tr><?php endforeach?></table>
